function openJournal(chunks) {
  let iterator = null;
  let closed = false;
  let eof = false;
  let finalLinePending = false;
  let returned = false;
  let closePromise = null;
  let buffer = "";
  let lineNumber = 1;
  const decoder = new TextDecoder();

  async function finishEarly() {
    if (returned || !iterator || eof) return;
    returned = true;

    const returnMethod = iterator.return;
    if (typeof returnMethod === "function") {
      await returnMethod.call(iterator);
    }
  }

  function eventFor(text, line) {
    if (text.trim().length === 0) return null;

    try {
      return { done: false, value: { line, ok: true, value: JSON.parse(text) } };
    } catch {
      return { done: false, value: { line, ok: false, text } };
    }
  }

  async function next() {
    if (closed) return { done: true, value: undefined };

    try {
      if (!iterator) {
        iterator = chunks[Symbol.asyncIterator]();
      }

      while (true) {
        const newline = buffer.indexOf("\n");

        if (newline !== -1) {
          let text = buffer.slice(0, newline);
          buffer = buffer.slice(newline + 1);

          if (text.endsWith("\r")) text = text.slice(0, -1);

          const currentLine = lineNumber++;
          const event = eventFor(text, currentLine);
          if (event) return event;
          continue;
        }

        if (eof) {
          if (!finalLinePending) {
            closed = true;
            return { done: true, value: undefined };
          }

          finalLinePending = false;
          const text = buffer;
          buffer = "";

          const event = eventFor(text, lineNumber);
          if (event) return event;

          closed = true;
          return { done: true, value: undefined };
        }

        const result = await iterator.next();

        if (result.done) {
          eof = true;
          buffer += decoder.decode();
          finalLinePending = true;
        } else {
          buffer += decoder.decode(result.value, { stream: true });
        }
      }
    } catch (error) {
      closed = true;

      try {
        await finishEarly();
      } catch {
        // Preserve the original read error.
      }

      throw error;
    }
  }

  async function close() {
    if (closePromise) return closePromise;

    closed = true;
    closePromise = finishEarly();
    return closePromise;
  }

  return { next, close };
}
